import java.util.Arrays;
import java.util.List;

public class GenericExample {
    // Generic class: T is a placeholder filled in by each use (Box<String>, Box<Integer>)
    static class Box<T> {
        private T content;

        void set(T content) { this.content = content; }

        T get() { return content; }
    }

    record Pair<K, V>(K key, V value) {}

    // Generic method: works for any reference element type
    static <T> void swap(T[] array, int i, int j) {
        T temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    // Bounded: T must be a Number, so doubleValue() is available
    static <T extends Number> double average(T[] numbers) {
        double sum = 0.0;
        for (T num : numbers) sum += num.doubleValue();
        return sum / numbers.length;
    }

    // Bounded: T must be Comparable to itself, so compareTo() is available
    static <T extends Comparable<T>> T max(List<T> items) {
        T best = items.get(0);
        for (T item : items) {
            if (item.compareTo(best) > 0) best = item;
        }
        return best;
    }

    public static void main(String[] args) {
        Box<String> word = new Box<>();
        word.set("hello");
        String text = word.get();                 // no cast needed
        System.out.println("Box<String> holds: " + text + " (length " + text.length() + ")");

        Box<Integer> count = new Box<>();
        count.set(42);                            // autoboxed int -> Integer
        int doubled = count.get() * 2;
        System.out.println("Box<Integer> holds: " + count.get() + ", doubled: " + doubled);

        String[] letters = {"a", "b", "c"};
        System.out.println("before swap: " + Arrays.toString(letters));
        swap(letters, 0, 2);                      // T inferred as String
        System.out.println("after swap(0, 2): " + Arrays.toString(letters));

        System.out.println("average(Integer[] {1, 2, 3, 4}) = " + String.format("%.2f", average(new Integer[]{1, 2, 3, 4})));
        System.out.println("average(Double[] {1.5, 2.5}) = " + String.format("%.2f", average(new Double[]{1.5, 2.5})));
        System.out.println("max([3, 9, 4]) = " + max(List.of(3, 9, 4)));
        System.out.println("max([pear, apple, fig]) = " + max(List.of("pear", "apple", "fig")));

        Pair<String, Integer> pair = new Pair<>("age", 30);
        System.out.println("Pair<String, Integer>: " + pair.key() + " -> " + pair.value());
    }
}

