#include <iostream>
#include <string>
#include <type_traits>
#include <utility>
#include <vector>

// Class template: the compiler generates a separate Box for each T (no erasure in C++)
template <typename T>
class Box {
    T content{};

public:
    void set(T value) { content = std::move(value); }
    const T& get() const { return content; }
};

template <typename K, typename V>
struct Pair {
    K key;
    V value;
};

template <typename T>
void swapAt(std::vector<T>& array, size_t i, size_t j) {
    T temp = array[i];
    array[i] = array[j];
    array[j] = temp;
}

// C++17 expresses the "Number" bound with a type trait check
template <typename T>
double average(const std::vector<T>& numbers) {
    static_assert(std::is_arithmetic_v<T>, "average needs a numeric type");
    double sum = 0.0;
    for (const T& n : numbers) sum += n;
    return sum / numbers.size();
}

// The "Comparable" bound is implicit: this only compiles if T supports operator<
template <typename T>
T maxOf(const std::vector<T>& items) {
    T best = items[0];
    for (const T& item : items) {
        if (best < item) best = item;
    }
    return best;
}

std::string show(const std::vector<std::string>& v) {
    std::string s = "[";
    for (size_t i = 0; i < v.size(); ++i) s += (i ? ", " : "") + v[i];
    return s + "]";
}

