    Box<std::string> word;
    word.set("hello");
    std::string text = word.get();
    std::cout << "Box<String> holds: " << text << " (length " << text.size() << ")\n";

    Box<int> count;  // C++ templates accept primitives directly; Java needs Integer
    count.set(42);
    std::cout << "Box<Integer> holds: " << count.get() << ", doubled: " << count.get() * 2 << "\n";

    std::vector<std::string> letters = {"a", "b", "c"};
    std::cout << "before swap: " << show(letters) << "\n";
    swapAt(letters, 0, 2);
    std::cout << "after swap(0, 2): " << show(letters) << "\n";

    std::printf("average(Integer[] {1, 2, 3, 4}) = %.2f\n", average(std::vector<int>{1, 2, 3, 4}));
    std::printf("average(Double[] {1.5, 2.5}) = %.2f\n", average(std::vector<double>{1.5, 2.5}));
