import java.util.ArrayList;
import java.util.List;
import java.util.NoSuchElementException;

public class GenericClassesStack {
    public static void main(String[] args) {
        Stack<String> words = new Stack<>();
        words.push("a");
        words.push("b");
        words.push("c");
        System.out.println("push a, b, c -> " + words);
        String top = words.pop();                  // returns String: no cast
        System.out.println("pop -> " + top + ", now " + words);
        // words.push(42);                         // compile error: int is not a String

        Stack<Integer> nums = new Stack<>();
        for (int n : new int[]{10, 20, 30}) nums.push(n);   // autoboxing int -> Integer
        int sum = 0;
        StringBuilder order = new StringBuilder();
        while (!nums.isEmpty()) {
            int value = nums.pop();                // unboxing Integer -> int
            order.append(value).append(' ');
            sum += value;
        }
        System.out.println("Stack<Integer> popped " + order.toString().trim() + ", sum = " + sum);

        try {
            nums.pop();
        } catch (NoSuchElementException e) {
            System.out.println("pop on empty stack -> " + e.getMessage());
        }

        Pair<String, Integer> pair = new Pair<>("Ada", 36);
        Pair<Integer, String> swapped = pair.swap();   // type arguments flip too
        System.out.println("pair " + pair + ", swapped " + swapped);
        System.out.println("swapped.first() + 1 = " + (swapped.first() + 1));   // first() is an Integer
    }
}

class Stack<T> {
    private final List<T> items = new ArrayList<>();

    void push(T item) { items.add(item); }

    T pop() {
        if (items.isEmpty()) throw new NoSuchElementException("stack is empty");
        return items.remove(items.size() - 1);
    }

    boolean isEmpty() { return items.isEmpty(); }

    @Override
    public String toString() { return items.toString(); }
}

record Pair<A, B>(A first, B second) {
    Pair<B, A> swap() { return new Pair<>(second, first); }

    @Override
    public String toString() { return "(" + first + ", " + second + ")"; }
}

