#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

// A class template is instantiated separately for each T (Stack<std::string>, Stack<int>)
template <typename T>
class Stack {
    std::vector<T> items;

public:
    void push(const T& item) { items.push_back(item); }

    T pop() {
        if (items.empty()) throw std::out_of_range("stack is empty");
        T top = items.back();
        items.pop_back();
        return top;
    }

    bool isEmpty() const { return items.empty(); }

    std::string toString() const {
        std::ostringstream out;
        out << "[";
        for (size_t i = 0; i < items.size(); ++i) out << (i ? ", " : "") << items[i];
        out << "]";
        return out.str();
    }
};

template <typename A, typename B>
struct Pair {
    A first;
    B second;

    Pair<B, A> swap() const { return {second, first}; }

    std::string toString() const {
        std::ostringstream out;
        out << "(" << first << ", " << second << ")";
        return out.str();
    }
};

int main() {
    Stack<std::string> words;
    words.push("a");
    words.push("b");
    words.push("c");
    std::cout << "push a, b, c -> " << words.toString() << "\n";
    std::string top = words.pop();
    std::cout << "pop -> " << top << ", now " << words.toString() << "\n";

    Stack<int> nums;  // no boxing in C++: the template stores plain ints
    for (int n : {10, 20, 30}) nums.push(n);
    int sum = 0;
    std::string order;
    while (!nums.isEmpty()) {
        int value = nums.pop();
        order += (order.empty() ? "" : " ") + std::to_string(value);
        sum += value;
    }
    std::cout << "Stack<Integer> popped " << order << ", sum = " << sum << "\n";

    try {
        nums.pop();
    } catch (const std::out_of_range& e) {
        std::cout << "pop on empty stack -> " << e.what() << "\n";
