import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class GenericMethodsDemo {
    public static void main(String[] args) {
        String[] colors = {"red", "green", "blue"};
        System.out.println("before swap: " + Arrays.toString(colors));
        Util.swap(colors, 0, 2);                       // T inferred as String
        System.out.println("swap(colors, 0, 2): " + Arrays.toString(colors));

        Integer[] nums = {1, 2, 3};                    // Integer[], not int[]: T must be a reference type
        Util.swap(nums, 1, 2);                         // T inferred as Integer
        System.out.println("swap(nums, 1, 2): " + Arrays.toString(nums));

        System.out.println("repeat(\"ab\", 3): " + Util.repeat("ab", 3));
        System.out.println("repeat(7, 2): " + Util.repeat(7, 2));

        System.out.println("firstOrDefault([], \"none\"): " + Util.firstOrDefault(List.of(), "none"));
        System.out.println("firstOrDefault([x, y], \"none\"): " + Util.firstOrDefault(List.of("x", "y"), "none"));

        // Explicit type witness: rarely needed, but shows T is an argument of the call
        List<Double> halves = Util.<Double>repeat(0.5, 2);
        System.out.println("Util.<Double>repeat(0.5, 2): " + halves);
    }
}

class Util {
    // <T> before the return type declares the method's own type parameter
    static <T> void swap(T[] a, int i, int j) {
        T tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    static <T> List<T> repeat(T value, int times) {
        List<T> out = new ArrayList<>();
        for (int i = 0; i < times; i++) out.add(value);
        return out;
    }

    static <T> T firstOrDefault(List<T> list, T fallback) {
        return list.isEmpty() ? fallback : list.get(0);
    }
}

