import java.util.ArrayList;
import java.util.List;

public class WildcardsPecs {
    // Producer: we only READ Numbers from src, so accept any List of a Number subtype
    static double sum(List<? extends Number> src) {
        double total = 0;
        for (Number n : src) total += n.doubleValue();
        // src.add(1);   // compile error: the real element type might be Double
        return total;
    }

    // Consumer: we only WRITE Integers into dest, so accept any List of an Integer supertype
    static void addSquares(List<? super Integer> dest, int n) {
        for (int i = 1; i <= n; i++) dest.add(i * i);
    }

    // PECS in one signature (compare Collections.copy)
    static <T> void copy(List<? super T> dest, List<? extends T> src) {
        for (T item : src) dest.add(item);
    }

    public static void main(String[] args) {
        List<Integer> ints = List.of(1, 2, 3);
        List<Double> doubles = List.of(1.5, 2.5);
        // List<Number> nums = ints;   // compile error: generics are invariant

        System.out.println("sum(List<Integer> " + ints + ") = " + String.format("%.2f", sum(ints)));
        System.out.println("sum(List<Double> " + doubles + ") = " + String.format("%.2f", sum(doubles)));

        List<Number> numbers = new ArrayList<>(List.of(0.5));
        addSquares(numbers, 3);
        System.out.println("addSquares(List<Number>, 3): " + numbers);

        List<Integer> squares = new ArrayList<>();
        addSquares(squares, 4);
        System.out.println("addSquares(List<Integer>, 4): " + squares);

        List<Number> target = new ArrayList<>();
        copy(target, ints);       // T = Number: dest is List<Number>, src is List<Integer>
        copy(target, doubles);
        System.out.println("copy Integers then Doubles into List<Number>: " + target);
    }
}

