#include <cstdio>
#include <iostream>
#include <sstream>
#include <string>
#include <type_traits>
#include <vector>

// C++ templates have no wildcards or variance. The closest equivalent is a template that
// accepts any element type and checks the "bound" with static_assert at compile time.
template <typename T>
double sum(const std::vector<T>& src) {  // like List<? extends Number>
    static_assert(std::is_arithmetic_v<T>, "elements must be numbers");
    double total = 0;
    for (const T& n : src) total += n;
    return total;
}

template <typename T>
void addSquares(std::vector<T>& dest, int n) {  // like List<? super Integer>
    static_assert(std::is_convertible_v<int, T>, "dest must be able to hold an int");
    for (int i = 1; i <= n; i++) dest.push_back(i * i);
}

template <typename D, typename S>
void copy(std::vector<D>& dest, const std::vector<S>& src) {
    static_assert(std::is_convertible_v<S, D>, "src elements must fit in dest");
    for (const S& item : src) dest.push_back(item);
}

template <typename T>
std::string show(const std::vector<T>& v) {
    std::ostringstream out;  // default stream formatting prints 1.0 as "1"
    out << "[";
    for (size_t i = 0; i < v.size(); ++i) out << (i ? ", " : "") << v[i];
    out << "]";
    return out.str();
}

int main() {
    std::vector<int> ints = {1, 2, 3};
    std::vector<double> doubles = {1.5, 2.5};

    std::printf("sum(List<Integer> %s) = %.2f\n", show(ints).c_str(), sum(ints));
    std::printf("sum(List<Double> %s) = %.2f\n", show(doubles).c_str(), sum(doubles));

    // vector<double> stands in for List<Number>: it can hold the ints we add
    std::vector<double> numbers = {0.5};
    addSquares(numbers, 3);
    std::cout << "addSquares(List<Number>, 3): " << show(numbers) << "\n";

    std::vector<int> squares;
    addSquares(squares, 4);
    std::cout << "addSquares(List<Integer>, 4): " << show(squares) << "\n";

    std::vector<double> target;
    copy(target, ints);
    copy(target, doubles);
    std::cout << "copy Integers then Doubles into List<Number>: " << show(target) << "\n";
}

