import java.util.ArrayList;
import java.util.List;

public class TypeErasureDemo {
    @SuppressWarnings({"rawtypes", "unchecked"})
    public static void main(String[] args) {
        List<String> strings = new ArrayList<>();
        List<Integer> numbers = new ArrayList<>();
        // Type arguments are erased: both lists are plain ArrayList objects at runtime
        System.out.println("same runtime class: " + (strings.getClass() == numbers.getClass()));
        // if (strings instanceof List<String>) {}   // compile error: cannot test an erased type

        strings.add("hello");
        List raw = strings;          // raw type: generic checks are switched off
        raw.add(42);                 // heap pollution: an Integer inside a List<String>
        System.out.println("after raw add, size = " + strings.size());
        System.out.println("contents: " + strings);

        for (int i = 0; i < strings.size(); i++) {
            try {
                String s = strings.get(i);   // compiled as (String) strings.get(i)
                System.out.println("get(" + i + ") as String -> " + s);
            } catch (ClassCastException e) {
                System.out.println("get(" + i + ") as String -> cast failed: element is not a String");
            }
        }
    }
}

