#include <any>
#include <iostream>
#include <memory>
#include <string>
#include <typeinfo>
#include <vector>

// C++ templates are NOT erased: std::vector<int> and std::vector<std::string> are different
// types. To model Java, every JList<T> stores its elements in one erased container of std::any.
using Erased = std::vector<std::any>;

template <typename T>
class JList {
    std::shared_ptr<Erased> data = std::make_shared<Erased>();

public:
    void add(const T& value) { data->push_back(value); }
    T get(size_t i) const { return std::any_cast<T>(data->at(i)); }  // the "inserted cast"
    size_t size() const { return data->size(); }
    Erased& raw() { return *data; }  // like a raw List: no element type at all
    const std::type_info& runtimeClass() const { return typeid(*data); }
};

std::string describe(const std::any& a) {
    if (a.type() == typeid(std::string)) return std::any_cast<std::string>(a);
    if (a.type() == typeid(int)) return std::to_string(std::any_cast<int>(a));
    return "?";
}

int main() {
    JList<std::string> strings;
    JList<int> numbers;
    std::cout << std::boolalpha;
    std::cout << "same runtime class: " << (strings.runtimeClass() == numbers.runtimeClass()) << "\n";

    strings.add("hello");
    strings.raw().push_back(42);  // heap pollution through the raw view
    std::cout << "after raw add, size = " << strings.size() << "\n";
    std::cout << "contents: [" << describe(strings.raw()[0]) << ", " << describe(strings.raw()[1]) << "]\n";

    for (size_t i = 0; i < strings.size(); i++) {
        try {
            std::string s = strings.get(i);
            std::cout << "get(" << i << ") as String -> " << s << "\n";
        } catch (const std::bad_any_cast&) {
            std::cout << "get(" << i << ") as String -> cast failed: element is not a String\n";
        }
    }
}

