import java.util.List;

public class BoundedTypes {
    // Bound: T must be Comparable to itself, so compareTo is available
    static <T extends Comparable<T>> T max(List<T> items) {
        T best = items.get(0);
        for (T item : items) {
            if (item.compareTo(best) > 0) best = item;
        }
        return best;
    }

    // Bound: T must be a Number, so doubleValue is available
    static <T extends Number> double average(List<T> nums) {
        double sum = 0;
        for (T n : nums) sum += n.doubleValue();
        return sum / nums.size();
    }

    // Multiple bounds: a class first, then interfaces joined with &
    static <T extends Number & Comparable<T>> String range(List<T> nums) {
        T lo = nums.get(0);
        T hi = nums.get(0);
        for (T n : nums) {
            if (n.compareTo(lo) < 0) lo = n;
            if (n.compareTo(hi) > 0) hi = n;
        }
        return lo + ".." + hi + " (span " + String.format("%.2f", hi.doubleValue() - lo.doubleValue()) + ")";
    }

    public static void main(String[] args) {
        System.out.println("max([3, 9, 4]) = " + max(List.of(3, 9, 4)));
        System.out.println("max([pear, apple, fig]) = " + max(List.of("pear", "apple", "fig")));
        // max(List.of(new Object()));   // compile error: Object is not Comparable

        System.out.println("average([1, 2, 3, 4]) = " + String.format("%.2f", average(List.of(1, 2, 3, 4))));
        System.out.println("average([0.5, 1.5]) = " + String.format("%.2f", average(List.of(0.5, 1.5))));
        // average(List.of("a"));        // compile error: String is not a Number

        System.out.println("range([7, 2, 9]) = " + range(List.of(7, 2, 9)));
        System.out.println("range([2.5, -1.5]) = " + range(List.of(2.5, -1.5)));
    }
}

