#include <cstdio>
#include <sstream>
#include <string>
#include <type_traits>
#include <vector>

// Implicit bound: this compiles only for types that support operator<
// (C++20 can state it explicitly: template <std::totally_ordered T>)
template <typename T>
T maxOf(const std::vector<T>& items) {
    T best = items[0];
    for (const T& item : items) {
        if (best < item) best = item;
    }
    return best;
}

// Explicit bound checked at compile time, like <T extends Number>
template <typename T>
double average(const std::vector<T>& nums) {
    static_assert(std::is_arithmetic_v<T>, "T must be a number");
    double sum = 0;
    for (const T& n : nums) sum += n;
    return sum / nums.size();
}

// Both requirements at once, like <T extends Number & Comparable<T>>
template <typename T>
std::string range(const std::vector<T>& nums) {
    static_assert(std::is_arithmetic_v<T>, "T must be a number");
    T lo = nums[0];
    T hi = nums[0];
    for (const T& n : nums) {
        if (n < lo) lo = n;
        if (hi < n) hi = n;
    }
    std::ostringstream out;
    out << lo << ".." << hi;
    char span[32];
    std::snprintf(span, sizeof span, " (span %.2f)", static_cast<double>(hi) - static_cast<double>(lo));
    return out.str() + span;
}

int main() {
    std::printf("max([3, 9, 4]) = %d\n", maxOf(std::vector<int>{3, 9, 4}));
    std::printf("max([pear, apple, fig]) = %s\n", maxOf(std::vector<std::string>{"pear", "apple", "fig"}).c_str());

    std::printf("average([1, 2, 3, 4]) = %.2f\n", average(std::vector<int>{1, 2, 3, 4}));
    std::printf("average([0.5, 1.5]) = %.2f\n", average(std::vector<double>{0.5, 1.5}));

    std::printf("range([7, 2, 9]) = %s\n", range(std::vector<int>{7, 2, 9}).c_str());
    std::printf("range([2.5, -1.5]) = %s\n", range(std::vector<double>{2.5, -1.5}).c_str());
}

